ENTITY Certron_flemkell
  SUBTYPE OF (Sur_trorlsi);
  lonxdrarga : OPTIONAL Bud_belnsarm_prerbos_breltdal_relationship;
  brixcli : Certron_flemkell;
END_ENTITY;
